package com.optarena.app

import java.time.LocalDate

fun addBusinessDays(start: LocalDate, n: Int): LocalDate {
    if (n == 0) {
        return start
    }
    val weeks = n / 5
    val remainder = n % 5
    val calendarDays = weeks * 7 + remainder
    return start.plusDays(calendarDays.toLong())
}

