package com.optarena.app

import java.time.LocalDate
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class DatesTest {
    @Test
    fun zeroReturnsStartUnchanged() {
        val d = LocalDate.of(2024, 6, 1) // Saturday
        assertEquals(d, addBusinessDays(d, 0))
    }

    @Test
    fun fridayPlusOneSkipsWeekend() {
        val friday = LocalDate.of(2024, 5, 31)
        assertEquals(LocalDate.of(2024, 6, 3), addBusinessDays(friday, 1))
    }

    @Test
    fun mondayPlusFiveLandsNextMonday() {
        val monday = LocalDate.of(2024, 5, 27)
        assertEquals(LocalDate.of(2024, 6, 3), addBusinessDays(monday, 5))
    }

    @Test
    fun crossesMonthAndYearBoundary() {
        val friday = LocalDate.of(2024, 12, 27)
        assertEquals(LocalDate.of(2025, 1, 1), addBusinessDays(friday, 3))
    }

    @Test
    fun startingOnAWeekendStillCountsCorrectly() {
        val saturday = LocalDate.of(2024, 6, 1)
        assertEquals(LocalDate.of(2024, 6, 3), addBusinessDays(saturday, 1))
    }
}
